'use strict';
(() => {
  const A=window.BrainApp, R=window.ResearchCore, W=window.WorkspaceCore, T=window.I18n, esc=A.esc;
  const KEY='brain-studio-workspace-v2';
  const instruments=()=>[...R.instruments,...W.instruments];
  const descriptor=id=>instruments().find(x=>x.id===id);
  const engine=id=>R.instruments.some(x=>x.id===id)?R:W;
  const tr=text=>T.t(text);
  const answerLanguages=(d,answers,record)=>Object.fromEntries(d.items.filter(item=>Object.hasOwn(answers,item.id)).map(item=>[item.id,T.languages.some(x=>x.code===record?.[item.id])?record[item.id]:'und']));
  const administrationLanguage=record=>{const values=[...new Set(Object.values(record))];return values.length===1?values[0]:'mul';};
  const validInterestOrder=(result,order)=>Array.isArray(order)&&order.length===3&&new Set(order).size===3&&order.every(id=>result.topThemes?.includes(id))&&order.map(id=>result.scales.find(scale=>scale.id===id)?.sum).every((sum,index)=>sum===result.scales.map(scale=>scale.sum).sort((a,b)=>b-a)[index]);
  const sourceLink=url=>typeof url==='string'&&/^https:\/\//.test(url)?`<a href="${esc(url)}" data-source-link data-i18n-skip>${esc(url)}</a>`:'';
  const h=text=>esc(tr(text));
  let data={drafts:{},profiles:[],models:[],plans:[],notes:{},feedbacks:[],rubrics:[]};
  let activeInstrument='ipip-50',activeProfile=null,activeRole='project-manager',activeFeedback='leadership';
  let observerDraft=[{role:'self',ratings:{},priorities:[]},{role:'manager',ratings:{},priorities:[]}];
  let feedbackResult=null,saveFailed=false;
  function cleanProfile(value){if(!value||!descriptor(value.instrumentId)||typeof value.name!=='string'||!Number.isFinite(value.date)||typeof value.id!=='string'||value.instrumentVersion!==descriptor(value.instrumentId).metadata.version||value.date<0||value.date>8640000000000000)return null;try{const answers=engine(value.instrumentId).validate(value.instrumentId,value.answers);engine(value.instrumentId).score(value.instrumentId,answers);return {id:value.id.slice(0,100),instrumentVersion:value.instrumentVersion,instrumentId:value.instrumentId,name:value.name.slice(0,80),date:value.date,elapsedWallTimeMs:Number.isFinite(value.elapsedWallTimeMs)&&value.elapsedWallTimeMs>=0?value.elapsedWallTimeMs:null,language:administrationLanguage(answerLanguages(descriptor(value.instrumentId),answers,value.answerLanguages)),answerLanguages:answerLanguages(descriptor(value.instrumentId),answers,value.answerLanguages),interestOrder:value.instrumentId==='onet-short-form-60'&&validInterestOrder(engine(value.instrumentId).score(value.instrumentId,answers),value.interestOrder)?value.interestOrder:[],answers};}catch{return null;}}
  try {const raw=localStorage.getItem(KEY);if(raw&&raw.length<=2000000){const saved=JSON.parse(raw);if(saved&&typeof saved==='object'&&!Array.isArray(saved)){data.profiles=Array.isArray(saved.profiles)?saved.profiles.map(cleanProfile).filter(Boolean).filter((profile,index,profiles)=>profiles.findIndex(other=>other.id===profile.id)===index).slice(0,100):[];for(const instrument of instruments()){const draft=saved.drafts?.[instrument.id];if(draft&&typeof draft==='object'){data.drafts[instrument.id]={answers:engine(instrument.id).validate(instrument.id,draft.answers),index:Number.isInteger(draft.index)&&draft.index>=0&&draft.index<instrument.items.length?draft.index:0,name:typeof draft.name==='string'?draft.name.slice(0,80):'',started:Number.isFinite(draft.started)?draft.started:Date.now(),answerLanguages:answerLanguages(instrument,engine(instrument.id).validate(instrument.id,draft.answers),draft.answerLanguages),originalEnglish:draft.originalEnglish!==false};}}data.models=Array.isArray(saved.models)?saved.models.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&x.targets&&W.roles[0].targets&&Object.keys(W.roles[0].targets).every(k=>Array.isArray(x.targets[k])&&x.targets[k].length===2&&x.targets[k].every(n=>Number.isFinite(n)&&n>=1&&n<=5)&&x.targets[k][0]<=x.targets[k][1])).slice(0,30).map(x=>({id:x.id.slice(0,100),title:x.title.slice(0,100),targets:x.targets,source:'User-defined descriptive scenario'})):[];data.plans=Array.isArray(saved.plans)?saved.plans.filter(x=>x&&typeof x.id==='string'&&typeof x.action==='string'&&typeof x.outcome==='string').slice(0,100).map(x=>({id:x.id.slice(0,100),action:x.action.slice(0,500),outcome:x.outcome.slice(0,500),owner:typeof x.owner==='string'?x.owner.slice(0,80):'',due:typeof x.due==='string'?x.due.slice(0,10):'',followUp:typeof x.followUp==='string'?x.followUp.slice(0,10):'',notes:typeof x.notes==='string'?x.notes.slice(0,1000):'',done:x.done===true})):[];data.notes=saved.notes&&typeof saved.notes==='object'&&!Array.isArray(saved.notes)?Object.fromEntries(Object.entries(saved.notes).filter(([k,v])=>k.length<100&&typeof v==='string').slice(0,100).map(([k,v])=>[k,v.slice(0,5000)])):{};data.feedbacks=Array.isArray(saved.feedbacks)?saved.feedbacks.filter(x=>x&&typeof x.kind==='string'&&W.feedbackSets[x.kind]&&Array.isArray(x.raters)).slice(0,50).filter(x=>{try{W.feedback(x.raters,x.kind);return true;}catch{return false;}}):[];data.rubrics=Array.isArray(saved.rubrics)?saved.rubrics.filter(x=>x&&Array.isArray(x.rows)).slice(0,50).filter(x=>{try{W.skillRubric(x.rows);return true;}catch{return false;}}):[];}}}catch{saveFailed=true;}
  function save(){try{const serialized=JSON.stringify(data);if(serialized.length>2000000)throw new RangeError();localStorage.setItem(KEY,serialized);saveFailed=false;return true;}catch{saveFailed=true;A.toast('Your workspace could not be saved. Export a copy before closing.');return false;}}
  const title=(heading,sub,tag='YOUR WORKSPACE')=>`<div class="page-heading"><div><div class="eyebrow">${h(tag)}</div><h1>${h(heading)}</h1><p class="muted">${h(sub)}</p></div></div>`;
  function setHTML(html){A.setHTML(html);if(saveFailed){const n=document.createElement('div');n.className='storage-warning';n.textContent=tr('Your workspace could not be saved. Export a copy before closing.');document.getElementById('content').prepend(n);}}
  const nameHTML=name=>`<bdi data-i18n-skip>${esc(name||tr('Personal profile'))}</bdi>`;
  const num=n=>T.number(Number(Number(n).toFixed(2)));
  const fraction=(a,b)=>`<bdi dir="ltr">${num(a)} / ${num(b)}</bdi>`;
  const profileResult=p=>engine(p.instrumentId).score(p.instrumentId,p.answers);
  const original=d=>d.metadata?.sourceLanguage==='en'&&(d.id==='onet-short-form-60'||d.id==='skills-practice'||(d.id==='ipip-50'&&getDraft(d.id).originalEnglish));
  const skip=(text,preserve=false)=>preserve?`<span data-i18n-skip dir="ltr" lang="en">${esc(text)}</span>`:h(text);
  function getDraft(id){return data.drafts[id]||(data.drafts[id]={answers:{},index:0,name:'',started:Date.now(),answerLanguages:{},originalEnglish:true});}
  function latestProfile(instrumentId){return data.profiles.find(x=>!instrumentId||x.instrumentId===instrumentId);}
  function chooseProfile(instrumentId){let p=data.profiles.find(x=>x.id===activeProfile&&(!instrumentId||x.instrumentId===instrumentId));if(!p){p=latestProfile(instrumentId);activeProfile=p?.id||null;}return p;}
  function profileSelect(profiles=data.profiles){return `<label class="form-label" for="profile-select">${h('Select a saved profile')}</label><select id="profile-select" class="field">${profiles.map(p=>`<option value="${esc(p.id)}" ${p.id===activeProfile?'selected':''}>${esc(p.name||tr('Personal profile'))} · ${h(descriptor(p.instrumentId).title)} · ${esc(new Date(p.date).toLocaleDateString(T.language))}</option>`).join('')}</select>`;}
  function bindProfile(route){const e=document.getElementById('profile-select');if(e)e.onchange=()=>{activeProfile=e.value;A.navigate(route);};}
  function noProfiles(instrumentId){return `<div class="empty"><div class="eyebrow">${h('START WITH YOUR OWN ANSWERS')}</div><h2>${h('A profile is needed for this report.')}</h2><p>${h('Complete an assessment and save its report. Imported answer files are rescored before use.')}</p><button class="primary" id="empty-start">${h('Open assessment library')} ↗</button>${instrumentId?`<p class="note">${h(descriptor(instrumentId).title)}</p>`:''}</div>`;}
  function bindEmpty(){const e=document.getElementById('empty-start');if(e)e.onclick=()=>A.navigate('library');}
  function reportExport(report){return async()=>{try{const result=await window.desktop.exportJSON({schema:'brain-studio-report',version:2,language:T.language,...(typeof report==='function'?report():report)});A.toast(result.saved?'Report exported.':result.downloadRequested?'Download requested. Check your browser downloads.':'Export cancelled.');}catch{A.toast('The report could not be exported. Try another location.');}};}
  function bindPDF(id='report-pdf'){const button=document.getElementById(id);if(button)button.onclick=async()=>{let section=button;const content=document.getElementById('content');while(section.parentElement&&section.parentElement!==content)section=section.parentElement;const scoped=section!==content&&section.classList.contains('result-summary')||section.id==='feedback-result'||section.id==='team-result';if(scoped){document.body.dataset.printScope='report';section.classList.add('print-report');}try{const result=await window.desktop.exportPDF(T.language);if(result.saved)A.toast('PDF report saved.');else if(result.printRequested)A.toast('Print dialog opened. Choose Save as PDF to save a report.');}catch{A.toast('The PDF could not be saved. Please try another folder.');}finally{delete document.body.dataset.printScope;section.classList.remove('print-report');}};}
  function instrumentBoundary(d,translated=false){const text=d.id==='ipip-50'?(translated?'Translated adaptation: the wording has not been psychometrically validated in this language. Raw scoring remains the published arithmetic.':'Published English items and scoring keys are preserved. A software score is not a clinical diagnosis or a population percentile.'):d.id==='onet-short-form-60'?'Original English O*NET activities and instructions are preserved under their redistribution license. Interests describe activities you like, not ability or predicted career success.':d.metadata.validationStatus;return `<div class="method-note"><strong>${h('Method and interpretation')}</strong><p>${h(text)}</p>${d.metadata.attribution?`<p class="note" data-i18n-skip dir="ltr" lang="en">${esc(d.metadata.attribution)}</p>`:''}<p>${(d.metadata.sourceURLs||[]).map(sourceLink).join('<br>')}${d.metadata.licenseURL?'<br>'+sourceLink(d.metadata.licenseURL):''}</p></div>`;}
  function library(){setHTML(title('Build a clearer working profile.','Choose a published assessment or an explicitly labeled reflection tool.','ASSESSMENT LIBRARY')+`<section class="professional-library">${instruments().map(d=>`<article class="info-card instrument-card"><div class="card-icon">${d.id==='ipip-50'?'◈':d.id==='onet-short-form-60'?'◎':'▤'}</div><span class="eyebrow">${h(R.instruments.includes(d)?'PUBLISHED SCORING':'CUSTOM DEVELOPMENT TOOL')}</span><h2>${h(d.title)}</h2><p>${h(d.description)}</p><div class="instrument-meta"><span>${num(d.items.length)} ${h('items')}</span><span>${h(d.id==='onet-short-form-60'?'Original English':'Self-report or practice')}</span></div><button class="primary" data-instrument="${d.id}"><span>${h(data.drafts[d.id]&&Object.keys(data.drafts[d.id].answers).length?'Resume assessment':'Start assessment')}</span><span class="arrow">↗</span></button></article>`).join('')}</section><div class="method-note"><strong>${h('What research can and cannot establish')}</strong><p>${h('Published source fidelity and correct arithmetic can be verified. Norms, clinical interpretation, predictive job validity, and translated equivalence require separate evidence. Custom tools are labeled accordingly.')}</p></div>`);document.querySelectorAll('[data-instrument]').forEach(button=>button.onclick=()=>{activeInstrument=button.dataset.instrument;A.navigate('instrument');});}
  function questionnaire(){const d=descriptor(activeInstrument),draft=getDraft(d.id),item=d.items[draft.index],preserve=original(d),answered=Object.keys(engine(d.id).validate(d.id,draft.answers)).length;setHTML(title(d.title,'Choose the response that describes you or the activity.','YOUR ASSESSMENT')+`<div class="question-layout professional-quiz"><section class="question-panel"><div class="quiz-top"><span>${h('Question')} ${fraction(draft.index+1,d.items.length)}</span><span>${num(answered)} ${h('answered')}</span></div><div class="progress"><div id="prof-progress" class="progress-fill"></div></div><div class="eyebrow">${h(d.id==='ipip-50'?'Your assessment':d.scales.find(s=>s.id===item.scaleId)?.title||'Your assessment')}</div><h2 id="professional-question">${skip(item.prompt,preserve)}</h2><p class="question-help">${h(d.id==='onet-short-form-60'?'Mark each activity explicitly as selected or not selected.':'Your answers can be reviewed before or after saving.')}</p><div class="options" role="group" aria-labelledby="professional-question">${d.responseOptions.map((o,index)=>`<button class="option pro-option ${draft.answers[item.id]===o.value?'selected':''}" data-prof-value="${o.value}" aria-pressed="${draft.answers[item.id]===o.value}"><span class="option-key">${num(index+1)}</span><span>${skip(item.choices?item.choices[index]:o.label,preserve)}</span></button>`).join('')}</div><div class="quiz-actions"><button class="secondary" id="prof-back" ${draft.index===0?'disabled':''}>${h('← Previous')}</button><button class="primary" id="prof-next" ${draft.answers[item.id]===undefined?'disabled':''}>${h(draft.index===d.items.length-1?'Generate report':'Next question')} <span class="arrow">→</span></button></div><div class="save-state">${h(saveFailed?'Not saved on this device':'Saved automatically')}</div></section><aside class="quiz-side"><div class="side-card"><div class="eyebrow">${h('YOUR PROFILE')}</div><label class="form-label" for="professional-name"><span>${h('Your name')}</span> <span>${h('(optional)')}</span></label><input id="professional-name" maxlength="80" value="${esc(draft.name)}" placeholder="${h('Use a name or a private alias')}"><p>${h('Names and responses stay on this device. Choose what to include when exporting.')}</p>${d.id==='ipip-50'?`<label class="check-label"><input type="checkbox" id="original-english" ${draft.originalEnglish?'checked':''}>${h('Use published English wording')}</label>`:''}</div><div class="side-card"><div class="eyebrow">${h('QUESTION NAVIGATION')}</div><div class="question-dots">${d.items.map((q,i)=>`<button data-prof-question="${i}" class="${draft.answers[q.id]!==undefined?'answered ':''}${draft.index===i?'current':''}" aria-label="${h('Question')} ${num(i+1)}">${num(i+1)}</button>`).join('')}</div></div></aside></div><details class="source-instructions"><summary>${h('Read the complete assessment instructions')}</summary><p ${preserve?'data-i18n-skip':''}>${skip(d.instructions||d.description,preserve)}</p></details>${instrumentBoundary(d,d.id==='ipip-50'&&(!draft.originalEnglish||Object.values(draft.answerLanguages||{}).some(x=>x!=='en')))}`);document.getElementById('prof-progress').style.width=`${answered/d.items.length*100}%`;document.querySelectorAll('[data-prof-value]').forEach(button=>button.onclick=()=>{draft.answers[item.id]=Number(button.dataset.profValue);draft.answerLanguages=draft.answerLanguages||{};draft.answerLanguages[item.id]=preserve?'en':T.language;save();questionnaire();document.querySelector(`[data-prof-value="${draft.answers[item.id]}"]`).focus();});document.getElementById('prof-back').onclick=()=>{draft.index--;save();questionnaire();};document.getElementById('prof-next').onclick=()=>{if(draft.answers[item.id]===undefined)return;if(draft.index<d.items.length-1){draft.index++;save();questionnaire();return;}if(answered!==d.items.length){draft.index=d.items.findIndex(q=>draft.answers[q.id]===undefined);save();questionnaire();A.toast('Answer every item before generating a report.');return;}const id=d.id+'-'+Date.now();const profile={id,instrumentVersion:d.metadata.version,instrumentId:d.id,name:draft.name,date:Date.now(),elapsedWallTimeMs:Math.max(0,Date.now()-draft.started),language:administrationLanguage(answerLanguages(d,draft.answers,draft.answerLanguages)),answerLanguages:answerLanguages(d,draft.answers,draft.answerLanguages),answers:{...draft.answers}};data.profiles.unshift(profile);data.profiles=data.profiles.slice(0,100);if(!save()){A.toast('The report was calculated but could not be saved. Export your workspace.');}activeProfile=id;A.navigate('portfolio');};document.getElementById('professional-name').oninput=e=>{draft.name=e.target.value.slice(0,80);save();};const english=document.getElementById('original-english');if(english)english.onchange=()=>{draft.originalEnglish=english.checked;save();questionnaire();};document.querySelectorAll('[data-prof-question]').forEach(button=>button.onclick=()=>{draft.index=Number(button.dataset.profQuestion);save();questionnaire();});}
  function scaleTable(result){return `<div class="score-table"><div class="table-head"><span>${h('Dimension')}</span><span>${h('Raw score')}</span><span>${h('Item mean')}</span><span>${h('Possible range')}</span></div>${result.scales.map(scale=>`<div class="score-row"><span>${h(scale.title)}</span><strong>${num(scale.sum)}</strong><span>${num(scale.mean)}</span><span>${num(scale.min)}–${num(scale.max)}</span><div class="score-meter"><div data-meter="${scale.max===scale.min?0:(scale.sum-scale.min)/(scale.max-scale.min)*100}"></div></div></div>`).join('')}</div>`;}
  function drawMeters(){document.querySelectorAll('[data-meter]').forEach(node=>node.style.width=node.dataset.meter+'%');}
  function portfolio(){const p=chooseProfile();if(!p){setHTML(title('Your assessment portfolio.','Keep the instrument and method attached to every result.')+noProfiles());return bindEmpty();}const d=descriptor(p.instrumentId),result=profileResult(p);setHTML(title('Your assessment portfolio.','Raw scores, source identity, and practical reflection in one place.','INDIVIDUAL REPORT')+profileSelect()+`<section class="result-summary portfolio-report"><div class="report-ident"><div><span class="eyebrow">${h(d.title)}</span><h2>${nameHTML(p.name)}</h2><p class="muted"><bdi>${esc(new Date(p.date).toLocaleString(T.language))}</bdi> · ${num(result.answered)} ${h('responses')}</p></div><span class="profile-pill">${h(R.instruments.includes(d)?'Published scoring':'Custom reflection')}</span></div>${scaleTable(result)}<p class="note">${h('Bars show position within the response range, not population percentiles. A larger score is not automatically better.')}</p>${result.correct!==undefined?`<h3>${h('Task category breakdown')}</h3><p>${h('Authored task categories; difficulty is not calibrated.')}</p><div class="comparison-table">${[...new Set(result.reviews.map(review=>review.difficulty))].map(category=>{const reviews=result.reviews.filter(review=>review.difficulty===category);return `<div class="comparison-row"><span>${h(category)}</span><span>${fraction(reviews.filter(review=>review.isCorrect).length,reviews.length)}</span><span>${h('correct responses')}</span><span>${h('Attempted')} ${num(reviews.length)}</span></div>`;}).join('')}</div><div class="result-highlight">${fraction(result.correct,result.itemCount)} ${h('practice answers correct')}</div><details><summary>${h('Review answers and explanations')}</summary>${result.reviews.map(review=>`<article class="review-item" data-i18n-skip><strong>${esc(review.prompt)}</strong><p>${esc(review.chosen)} → ${esc(review.correct)}</p><p>${esc(review.explanation)}</p><p>${esc(review.difficulty)}</p></article>`).join('')}</details>`:''}${result.rankedThemes?`<section class="interest-themes"><h3>${h('Your interest themes')}</h3><p data-i18n-skip>${esc(d.interpretationInstructions)}</p><div class="theme-pills">${result.rankedThemes.map(group=>`<span class="profile-pill">${group.scaleIds.map(id=>h(d.scales.find(s=>s.id===id).title)).join(' / ')} · ${num(group.sum)}</span>`).join('')}</div><p>${h(result.tiesRequireChoice?'Tied interests require your own choice. No automatic three-letter code is assigned.':'The ordered themes describe your activity preferences. They do not predict career success.')}</p><form id="interest-order-form"><h3>${h('Choose your preferred order for tied interest themes')}</h3><p>${h('Choose three distinct themes in score order. Your choices are stored separately from calculated scores.')}</p><div class="form-grid">${[0,1,2].map(index=>`<label>${h('Preference')} ${num(index+1)}<select name="interest${index}" required><option value="">${h('Choose a theme')}</option>${result.topThemes.map(id=>`<option value="${esc(id)}" ${p.interestOrder?.[index]===id?'selected':''}>${h(d.scales.find(scale=>scale.id===id).title)}</option>`).join('')}</select></label>`).join('')}</div><button class="secondary" type="submit">${h('Save my interest preferences')}</button></form></section>`:''}${p.elapsedWallTimeMs!==null&&p.elapsedWallTimeMs!==undefined?`<p class="note">${h('Elapsed wall time, including breaks')} · ${num(p.elapsedWallTimeMs/60000)} ${h('minutes')}</p>`:''}${instrumentBoundary(d,p.instrumentId==='ipip-50'&&p.language!=='en')}<dl class="method-data"><dt>${h('Instrument version')}</dt><dd data-i18n-skip>${esc(d.metadata.version)}</dd><dt>${h('Questionnaire language')}</dt><dd data-i18n-skip>${esc(p.language)}</dd><dt>${h('Scoring method')}</dt><dd>${h('Published keyed sums for source instruments; explicit raw-response sums for custom tools. Practice tasks use their stated answer key.')}</dd><dt>${h('Source and license')}</dt><dd data-i18n-skip>${esc(d.metadata.license)}<br>${sourceLink(d.metadata.licenseURL)}<br>${(d.metadata.sourceURLs||[]).map(sourceLink).join('<br>')}</dd></dl><div class="result-actions"><button id="report-pdf" class="primary">${h('Export PDF ↗')}</button><button id="report-json" class="secondary">${h('Export selected report')}</button><button id="profile-answers" class="secondary">${h('Review answers')}</button><button id="profile-new" class="secondary">${h('Start new responses')}</button><button id="profile-coaching" class="text-button">${h('Open coaching and interview guide')}</button></div></section>`);bindProfile('portfolio');drawMeters();bindPDF();const interestForm=document.getElementById('interest-order-form');if(interestForm)interestForm.onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),order=[0,1,2].map(index=>form.get('interest'+index));if(!validInterestOrder(result,order))return A.toast('Choose three different themes in their calculated score order.');p.interestOrder=order;if(save())A.toast('Interest preferences saved separately from scores.');};document.getElementById('report-json').onclick=reportExport(()=>({type:'individual',profile:{...p,answers:undefined},result,attribution:d.metadata.attribution,limitations:d.metadata.limitations}));document.getElementById('profile-answers').onclick=()=>{activeInstrument=p.instrumentId;data.drafts[p.instrumentId]={answers:{...p.answers},index:0,name:p.name,started:Date.now(),answerLanguages:{...p.answerLanguages},originalEnglish:p.language==='en'};save();A.navigate('instrument');};document.getElementById('profile-new').onclick=()=>{activeInstrument=p.instrumentId;data.drafts[p.instrumentId]={answers:{},index:0,name:p.name,started:Date.now(),answerLanguages:{},originalEnglish:true};save();A.navigate('instrument');};document.getElementById('profile-coaching').onclick=()=>A.navigate('coaching');}
  function roles(){const p=chooseProfile('work-style');if(!p){setHTML(title('Explore role scenarios.','Compare working preferences with explicit, editable target ranges.')+noProfiles('work-style'));return bindEmpty();}const models=[...W.roles,...data.models];let model=models.find(x=>x.id===activeRole)||models[0];const comparison=W.compare(profileResult(p),model);setHTML(title('Explore role scenarios.','These illustrative ranges are planning scenarios, not job-success standards.','ROLE COMPARISON')+profileSelect(data.profiles.filter(x=>x.instrumentId==='work-style'))+`<label for="role-select" class="form-label">${h('Choose a role scenario')}</label><select id="role-select" class="field">${models.map(m=>`<option value="${esc(m.id)}" ${m.id===model.id?'selected':''}>${esc(m.title===model.title&&data.models.includes(m)?m.title:tr(m.title))}</option>`).join('')}</select><div class="result-summary"><h2 data-i18n-skip>${nameHTML(p.name)} · ${data.models.includes(model)?esc(model.title):h(model.title)}</h2><p class="note" data-i18n-skip>${esc(p.instrumentVersion)} · ${esc(p.language)}</p><div class="result-highlight">${fraction(comparison.within,comparison.total)} ${h('dimensions within the selected ranges')}</div><p>${h('A target-range match does not establish competence, compatibility, or employment suitability.')}</p><div class="comparison-table"><div class="comparison-row table-head"><span>${h('Dimension')}</span><span>${h('Your mean')}</span><span>${h('Target range')}</span><span>${h('Distance')}</span></div>${comparison.rows.map(row=>`<div class="comparison-row"><span>${h(row.title)}</span><strong>${num(row.actual)}</strong><span>${num(row.min)}–${num(row.max)}</span><span>${num(row.gap)}</span></div>`).join('')}</div><details><summary>${h('Create or edit a scenario')}</summary><form id="model-form"><label class="form-label" for="model-name">${h('Scenario name')}</label><input id="model-name" maxlength="100" value="${esc(model.title)}"><div class="model-grid">${comparison.rows.map(row=>`<label>${h(row.title)}<span><input type="number" min="1" max="5" step="0.25" data-target-min="${row.id}" value="${row.min}"><input type="number" min="1" max="5" step="0.25" data-target-max="${row.id}" value="${row.max}"></span></label>`).join('')}</div><button class="primary" type="submit">${h('Save custom scenario')}</button></form></details><div class="result-actions"><button id="report-pdf" class="secondary">${h('Export PDF ↗')}</button><button id="comparison-json" class="secondary">${h('Export comparison')}</button></div></div><h2 class="section-title">${h('Succession planning scenarios')}</h2><p class="muted">${h('Side-by-side descriptive scenarios. No hiring or succession recommendation is generated.')}</p><div class="scenario-list">${models.map(m=>{const c=W.compare(profileResult(p),m);return `<article class="history-row"><div><h3>${data.models.includes(m)?esc(m.title):h(m.title)}</h3><p>${fraction(c.within,c.total)} ${h('within range')} · ${h('Total distance')} ${num(c.totalDistance)}</p></div><button class="secondary" data-use-role="${m.id}">${h('View scenario')}</button></article>`;}).join('')}</div>`);bindProfile('roles');document.getElementById('role-select').onchange=e=>{activeRole=e.target.value;roles();};document.querySelectorAll('[data-use-role]').forEach(button=>button.onclick=()=>{activeRole=button.dataset.useRole;roles();});document.getElementById('model-form').onsubmit=e=>{e.preventDefault();const title=document.getElementById('model-name').value.trim();if(!title)return A.toast('Enter a scenario name.');const targets=Object.fromEntries(comparison.rows.map(r=>[r.id,[Number(document.querySelector(`[data-target-min="${r.id}"]`).value),Number(document.querySelector(`[data-target-max="${r.id}"]`).value)]]));const newModel={id:'custom-'+Date.now(),title,targets,source:'User-defined descriptive scenario'};try{W.compare(profileResult(p),newModel);}catch{return A.toast('Each target needs a minimum and maximum between 1 and 5.');}data.models.unshift(newModel);data.models=data.models.slice(0,30);if(save()){activeRole=newModel.id;roles();A.toast('Custom scenario saved.');}};bindPDF();document.getElementById('comparison-json').onclick=reportExport({type:'role-comparison',profile:{...p,answers:undefined},model,comparison});}
  function coaching(){const p=chooseProfile();if(!p){setHTML(title('Turn reflection into a conversation.','Explore examples, questions, and small development experiments.')+noProfiles());return bindEmpty();}const result=profileResult(p);setHTML(title('Turn reflection into a conversation.','Use open-ended questions and evidence from real situations.','COACHING AND INTERVIEW')+profileSelect()+`<div class="method-note"><p>${h('These original discussion prompts are not a validated selection interview. Different preferences can be useful in different situations.')}</p></div><div class="coaching-grid">${result.scales.map(scale=>`<article class="info-card"><span class="eyebrow">${h(scale.title)}</span><h3>${h('Explore a real example')}</h3><p>${h(p.instrumentId==='skills-practice'?'Review attempted tasks, correct answers, and explanations. Recorded elapsed time describes the session, not a speed norm.':'Describe a recent situation that illustrates this preference. What did you do, what happened, and what evidence supports your interpretation?')}</p><h3>${h('Consider another approach')}</h3><p>${h(p.instrumentId==='skills-practice'?'Numerical, reasoning, and verbal tasks have an explicit answer key. They are not a normed aptitude or IQ test.':'When might a different approach work better? Try one small change and review the outcome rather than assuming the score predicts performance.')}</p><h3>${h('Interview discussion')}</h3><p>${h('Tell me about a difficult task, how you chose your approach, how you worked with others, and what you learned from the result.')}</p></article>`).join('')}</div><label class="form-label" for="coaching-notes">${h('Your examples and notes')}</label><textarea data-i18n-skip id="coaching-notes" rows="6" maxlength="5000">${esc(data.notes[p.id]||'')}</textarea><div class="result-actions"><button id="coaching-save" class="primary">${h('Save notes')}</button><button id="report-pdf" class="secondary">${h('Export PDF ↗')}</button><button id="coaching-export" class="secondary">${h('Export coaching report')}</button><button id="plan-open" class="text-button">${h('Create a development action')}</button></div>`);bindProfile('coaching');document.getElementById('coaching-save').onclick=()=>{data.notes[p.id]=document.getElementById('coaching-notes').value;if(save())A.toast('Notes saved on this device.');};document.getElementById('coaching-export').onclick=reportExport(()=>({type:'coaching',profile:{...p,answers:undefined},result,notes:data.notes[p.id]||'',limitations:['Original development prompts; not a validated selection interview']}));document.getElementById('plan-open').onclick=()=>A.navigate('development');bindPDF();}
  function development(){setHTML(title('Make the next step concrete.','Keep development actions separate from assessment scores.','DEVELOPMENT PLAN')+`<form id="plan-form" class="result-summary"><div class="form-grid"><label>${h('Action')}<textarea data-i18n-skip name="action" required maxlength="500" rows="2"></textarea></label><label>${h('Intended outcome')}<textarea data-i18n-skip name="outcome" required maxlength="500" rows="2"></textarea></label><label>${h('Owner or private alias')}<input name="owner" maxlength="80"></label><label>${h('Target date')}<input type="date" name="due"></label><label>${h('Follow-up date')}<input type="date" name="followUp"></label></div><button type="submit" class="primary">${h('Add development action')}</button></form><div class="plan-list">${data.plans.map(p=>`<article class="result-summary plan-item"><label class="check-label"><input type="checkbox" data-plan-done="${esc(p.id)}" ${p.done?'checked':''}>${h('Action completed')}</label><h3 data-i18n-skip>${esc(p.action)}</h3><p data-i18n-skip>${esc(p.outcome)}</p><p class="note">${h('Owner')} ${nameHTML(p.owner)} · ${h('Target date')} <bdi>${esc(p.due||'—')}</bdi> · ${h('Follow-up date')} <bdi>${esc(p.followUp||'—')}</bdi></p><label class="form-label">${h('Progress notes')}<textarea data-i18n-skip data-plan-note="${esc(p.id)}" rows="2" maxlength="1000">${esc(p.notes||'')}</textarea></label></article>`).join('')}</div><div class="result-actions"><button id="report-pdf" class="secondary">${h('Export PDF ↗')}</button><button id="plan-export" class="secondary">${h('Export development plan')}</button></div>`);document.getElementById('plan-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const plan={id:'plan-'+Date.now(),action:String(f.get('action')).trim(),outcome:String(f.get('outcome')).trim(),owner:String(f.get('owner')),due:String(f.get('due')),followUp:String(f.get('followUp')),notes:'',done:false};if(!plan.action||!plan.outcome)return;data.plans.unshift(plan);data.plans=data.plans.slice(0,100);if(save())development();};document.querySelectorAll('[data-plan-done]').forEach(input=>input.onchange=()=>{data.plans.find(p=>p.id===input.dataset.planDone).done=input.checked;save();});document.querySelectorAll('[data-plan-note]').forEach(input=>input.oninput=()=>{data.plans.find(p=>p.id===input.dataset.planNote).notes=input.value;save();});document.getElementById('plan-export').onclick=reportExport({type:'development-plan',actions:data.plans,limitations:['Progress is user-reported and is not a psychometric change score']});bindPDF();}
  function team(){setHTML(title('Compare perspectives, not people’s worth.','Use the same instrument for every selected person.','TEAM AND MANAGER COMPARISON')+`<div class="result-summary"><p>${h('Only compare profiles shared with you for this purpose. Small groups can reveal individual information. No relationship-success or team-effectiveness prediction is made.')}</p><div class="profile-checks">${data.profiles.map(p=>`<label class="check-label"><input type="checkbox" data-team-profile="${esc(p.id)}">${nameHTML(p.name)} · ${h(descriptor(p.instrumentId).title)}</label>`).join('')}</div><button id="team-calculate" class="primary">${h('Compare selected profiles')}</button></div><section id="team-result"></section>`);document.getElementById('team-calculate').onclick=()=>{const selected=[...document.querySelectorAll('[data-team-profile]:checked')].map(e=>data.profiles.find(p=>p.id===e.dataset.teamProfile));let rows;try{if(new Set(selected.map(p=>p.language)).size!==1||selected.some(p=>['mul','und'].includes(p.language)))throw new Error('Incompatible administration languages');rows=W.team(selected.map(profileResult));}catch{return A.toast('Select at least two profiles with the same instrument, version, and questionnaire language.');}const panel=document.getElementById('team-result');panel.innerHTML=`<div class="result-summary"><h2>${h(selected.length===2?'Person-to-person discussion':'Team dimension summary')}</h2><p>${num(selected.length)} ${h('selected profiles')} · ${h('Descriptive means and observed ranges only')} · ${h('Language adaptations and custom tools are not validated for group equivalence.')}</p><div class="comparison-table"><div class="comparison-row table-head"><span>${h('Dimension')}</span><span>${h('Group mean')}</span><span>${h('Observed range')}</span><span>${h('Valid responses')}</span></div>${rows.map(row=>`<div class="comparison-row"><span>${h(row.title)}</span><span>${num(row.mean)}</span><span>${num(row.min)}–${num(row.max)}</span><span>${num(row.count)}</span></div>`).join('')}</div>${selected.length===2?`<h3>${h('Individual perspectives and differences')}</h3><div class="comparison-table"><div class="comparison-row table-head"><span>${h('Dimension')}</span><span>${nameHTML(selected[0].name)}</span><span>${nameHTML(selected[1].name)}</span><span>${h('Difference')}</span></div>${rows.map(row=>{const a=profileResult(selected[0]).scales.find(scale=>scale.id===row.id).mean,b=profileResult(selected[1]).scales.find(scale=>scale.id===row.id).mean;return `<div class="comparison-row"><span>${h(row.title)}</span><span>${num(a)}</span><span>${num(b)}</span><span>${num(a-b)}</span></div>`;}).join('')}</div>`:''}<p>${h('Different preferences need not imply conflict. Discuss concrete examples and agree on a practical working arrangement.')}</p><div class="result-actions"><button id="report-pdf" class="secondary">${h('Export PDF ↗')}</button><button id="team-export" class="secondary">${h('Export selected team report')}</button></div></div>`;T.translateDOM(panel);document.getElementById('team-export').onclick=reportExport({type:'team',participants:selected.map(p=>({id:p.id,name:p.name,instrumentId:p.instrumentId,instrumentVersion:p.instrumentVersion,language:p.language})),rows,individualRows:selected.length===2?rows.map(row=>{const a=profileResult(selected[0]).scales.find(scale=>scale.id===row.id).mean,b=profileResult(selected[1]).scales.find(scale=>scale.id===row.id).mean;return {dimensionId:row.id,firstMean:a,secondMean:b,difference:a-b};}):undefined,limitations:['Selected participants only; no anonymity or predictive team validity is claimed','Language adaptations and custom tools are not validated for group equivalence.']});bindPDF();};}
  function feedback(){const themes=W.feedbackSets[activeFeedback];setHTML(title('Listen to more than one perspective.','Separate self ratings, observer roles, missing observations, and priorities.','MULTI-RATER DEVELOPMENT FEEDBACK')+`<div class="result-summary"><label class="form-label" for="feedback-kind">${h('Development framework')}</label><select id="feedback-kind" class="field">${[['leadership','Leadership 360 reflection'],['sales','Sales 180 reflection'],['service','Customer-service feedback']].map(([id,label])=>`<option value="${id}" ${activeFeedback===id?'selected':''}>${h(label)}</option>`).join('')}</select><p>${h('These custom frameworks have separate competency lists. They do not reproduce proprietary favorable zones, norms, or certified leadership scores.')}</p><label class="check-label"><input type="checkbox" id="privacy-mode" checked>${h('Hide observer means with fewer than three valid observers')}</label></div><div class="rater-list">${observerDraft.map((r,index)=>`<section class="result-summary rater-card"><label class="form-label">${h('Rater role')}<select class="field" data-rater-role="${index}" ${index===0?'disabled':''}>${['self','manager','peer','direct-report','observer','customer'].filter(role=>index===0?role==='self':role!=='self').map(role=>`<option value="${role}" ${r.role===role?'selected':''}>${h(role)}</option>`).join('')}</select></label><div class="ratings-grid">${themes.map((theme,i)=>`<label>${h(theme)}<select data-rater="${index}" data-competency="c${i}"><option value="">${h('Choose a rating')}</option><option value="null" ${r.ratings['c'+i]===null?'selected':''}>${h('Not observed')}</option>${[1,2,3,4,5].map(v=>`<option value="${v}" ${r.ratings['c'+i]===v?'selected':''}>${num(v)}</option>`).join('')}</select></label>`).join('')}</div><p>${h('Select up to three development priorities')}</p><div class="priorities-grid">${themes.map((theme,i)=>`<label class="check-label"><input type="checkbox" data-priority-rater="${index}" data-priority="${i}" ${r.priorities.includes(i)?'checked':''}>${h(theme)}</label>`).join('')}</div></section>`).join('')}</div><div class="result-actions"><button id="add-rater" class="secondary">${h('Add observer')}</button><button id="feedback-calculate" class="primary">${h('Generate feedback report')}</button></div><section id="feedback-result"></section><h2 class="section-title">${h('Saved feedback sessions')}</h2>${data.feedbacks.map((session,index)=>`<article class="history-row"><div><h3>${h({leadership:'Leadership development',sales:'Sales feedback',service:'Customer service feedback'}[session.kind])}</h3><p>${esc(new Date(session.date).toLocaleString(T.language))}</p></div><button class="secondary" data-open-feedback="${index}">${h('Reopen feedback session')}</button></article>`).join('')}`);document.querySelectorAll('[data-open-feedback]').forEach(button=>button.onclick=()=>{const session=data.feedbacks[Number(button.dataset.openFeedback)];activeFeedback=session.kind;observerDraft=JSON.parse(JSON.stringify(session.raters));feedback();document.getElementById('feedback-calculate').click();});document.getElementById('feedback-kind').onchange=e=>{activeFeedback=e.target.value;observerDraft=[{role:'self',ratings:{},priorities:[]},{role:'manager',ratings:{},priorities:[]}];feedback();};document.querySelectorAll('[data-rater-role]').forEach(e=>e.onchange=()=>observerDraft[Number(e.dataset.raterRole)].role=e.value);document.querySelectorAll('[data-rater]').forEach(e=>e.onchange=()=>{const r=observerDraft[Number(e.dataset.rater)];if(e.value==='')delete r.ratings[e.dataset.competency];else r.ratings[e.dataset.competency]=e.value==='null'?null:Number(e.value);});document.querySelectorAll('[data-priority-rater]').forEach(e=>e.onchange=()=>{const r=observerDraft[Number(e.dataset.priorityRater)],id=Number(e.dataset.priority);if(e.checked&&r.priorities.length>=3){e.checked=false;return A.toast('Choose no more than three priorities.');}r.priorities=e.checked?[...r.priorities,id]:r.priorities.filter(x=>x!==id);});document.getElementById('add-rater').onclick=()=>{if(observerDraft.length>=30)return A.toast('A feedback session supports up to 30 local raters.');observerDraft.push({role:'peer',ratings:{},priorities:[]});feedback();};document.getElementById('privacy-mode').onchange=()=>{const hadReport=document.getElementById('feedback-result').children.length>0;document.getElementById('feedback-result').replaceChildren();if(hadReport)document.getElementById('feedback-calculate').click();};document.getElementById('feedback-calculate').onclick=()=>{try{feedbackResult=W.feedback(observerDraft,activeFeedback);}catch{return A.toast('Rate every competency or explicitly select Not observed. Include self and at least one observer.');}const hide=document.getElementById('privacy-mode').checked,result=feedbackResult;const panel=document.getElementById('feedback-result');panel.innerHTML=`<div class="result-summary"><h2>${h({leadership:'Leadership development',sales:'Sales feedback',service:'Customer service feedback'}[activeFeedback])}</h2><p data-i18n-skip>${esc(result.version)}</p><h3>${h('Self and observer perspectives')}</h3><p>${h(result.privacy)}</p><p>${h(result.validationStatus)}</p><p>${h('Not observed responses are excluded from means. Differences are descriptive and use no favorable-zone cutoff.')}</p><div class="feedback-table"><div class="feedback-row table-head"><span>${h('Competency')}</span><span>${h('Self')}</span><span>${h('Observers')}</span><span>${h('Valid observers')}</span><span>${h('Difference')}</span></div>${result.rows.map(row=>`<div class="feedback-row"><span>${h(row.title)}</span><span>${row.self===null?'—':num(row.self)}</span><span>${row.othersMean===null?'—':hide&&row.raterCount<3?h('Suppressed'):num(row.othersMean)}</span><span>${num(row.raterCount)}</span><span>${row.gap===null||hide&&row.raterCount<3?'—':num(row.gap)}</span></div>`).join('')}</div><details><summary>${h('Observer groups and rating dispersion')}</summary>${result.rows.map(row=>`<article class="review-item"><strong>${h(row.title)}</strong><p>${h('Observer rating dispersion (SD)')} · ${row.raterCount<2||hide&&row.raterCount<3?h('Suppressed'):num(row.dispersion)}</p>${row.groups.map(group=>`<p>${h(group.role)} · ${num(group.count)} ${h('Valid observers')} · ${hide&&group.count<3?h('Suppressed'):group.mean===null?'—':num(group.mean)}</p>`).join('')}</article>`).join('')}</details>${result.priorities&&!hide?`<h3>${h('Priority overlap')}</h3><p>${h('Overlap is shared priorities divided by the union of both priority sets. It is not a competence score.')}</p>${result.priorities.map(p=>`<p>${h(p.role)} · ${fraction(p.shared,p.union)} · ${num(p.jaccard)}</p>`).join('')}`:''}<div class="result-actions"><button id="report-pdf" class="secondary">${h('Export PDF ↗')}</button><button id="feedback-export" class="secondary">${h('Export feedback report')}</button><button id="feedback-save" class="secondary">${h('Save feedback session')}</button></div></div>`;T.translateDOM(panel);document.getElementById('feedback-export').onclick=reportExport({type:'feedback',kind:activeFeedback,result:hide?{...result,priorities:null,rows:result.rows.map(row=>row.raterCount<3?{...row,othersMean:null,gap:null,groups:[],dispersion:null}:{...row,groups:row.groups.filter(group=>group.count>=3)})}:result,privacyMode:hide});document.getElementById('feedback-save').onclick=()=>{data.feedbacks.unshift({kind:activeFeedback,date:Date.now(),raters:JSON.parse(JSON.stringify(observerDraft))});data.feedbacks=data.feedbacks.slice(0,50);if(save())A.toast('Feedback session saved locally.');};bindPDF();};}
  function skills(){setHTML(title('Keep evidence behind every skill score.','Practice with explained answers or record an explicit points-based rubric.','SKILLS AND TOPICS')+`<div class="cards"><article class="info-card"><h2>${h('Explained practice')}</h2><p>${h('Numerical, reasoning, and verbal tasks have an explicit answer key. They are not a normed aptitude or IQ test.')}</p><button id="skills-start" class="primary">${h('Start skills practice')}</button></article><article class="info-card"><h2>${h('Topic and difficulty breakdown')}</h2><p>${h('Review attempted tasks, correct answers, and explanations. Recorded elapsed time describes the session, not a speed norm.')}</p></article><article class="info-card"><h2>${h('Partial-credit grading')}</h2><p>${h('Record earned and possible points for each task. Topic totals use actual point weights rather than treating every task as equal.')}</p></article></div><form id="rubric-form" class="result-summary"><h2>${h('Create a local grading rubric')}</h2><div id="rubric-rows">${Array.from({length:3},(_,i)=>`<div class="rubric-row"><input name="topic${i}" maxlength="80" placeholder="${h('Topic')}" required><input name="earned${i}" type="number" min="0" step="0.25" placeholder="${h('Earned points')}" required><input name="possible${i}" type="number" min="0.25" step="0.25" placeholder="${h('Possible points')}" required></div>`).join('')}</div><div class="result-actions"><button id="rubric-add" class="secondary" type="button">${h('Add graded task')}</button><button type="submit" class="primary">${h('Calculate topic totals')}</button></div></form><section id="rubric-result"></section><h2 class="section-title">${h('Saved grading records')}</h2>${data.rubrics.map((record,index)=>`<article class="history-row"><div><p>${esc(new Date(record.date).toLocaleString(T.language))} · ${num(record.rows.length)} ${h('tasks')}</p></div><button class="secondary" data-open-rubric="${index}">${h('Reopen grading record')}</button></article>`).join('')}`);document.getElementById('skills-start').onclick=()=>{activeInstrument='skills-practice';A.navigate('instrument');};const rowsContainer=document.getElementById('rubric-rows');document.getElementById('rubric-add').onclick=()=>{const index=rowsContainer.children.length;if(index>=100)return;const row=document.createElement('div');row.className='rubric-row';row.innerHTML=`<input name="topic${index}" maxlength="80" placeholder="${h('Topic')}" required><input name="earned${index}" type="number" min="0" step="0.25" placeholder="${h('Earned points')}" required><input name="possible${index}" type="number" min="0.25" step="0.25" placeholder="${h('Possible points')}" required>`;rowsContainer.append(row);};document.querySelectorAll('[data-open-rubric]').forEach(button=>button.onclick=()=>{const rows=data.rubrics[Number(button.dataset.openRubric)].rows;rowsContainer.innerHTML='';for(let index=0;index<rows.length;index++)document.getElementById('rubric-add').click();rows.forEach((row,index)=>{document.querySelector(`[name="topic${index}"]`).value=row.topic;document.querySelector(`[name="earned${index}"]`).value=row.earned;document.querySelector(`[name="possible${index}"]`).value=row.possible;});document.getElementById('rubric-form').requestSubmit();});document.getElementById('rubric-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),rows=Array.from({length:rowsContainer.children.length},(_,i)=>({topic:String(f.get('topic'+i)),earned:Number(f.get('earned'+i)),possible:Number(f.get('possible'+i))}));let result;try{result=W.skillRubric(rows);}catch{return A.toast('Each task needs earned points between zero and its positive possible points.');}const panel=document.getElementById('rubric-result');panel.innerHTML=`<div class="result-summary"><h2>${fraction(result.earned,result.possible)} ${h('points earned')}</h2>${result.groups.map(g=>`<p>${nameHTML(g.topic)} · ${fraction(g.earned,g.possible)} · ${num(g.count)} ${h('tasks')}</p>`).join('')}<p>${h(result.validationStatus)}</p><div class="result-actions"><button id="rubric-export" class="secondary">${h('Export grading report')}</button><button id="rubric-save" class="secondary">${h('Save grading record')}</button></div></div>`;T.translateDOM(panel);document.getElementById('rubric-export').onclick=reportExport({type:'skill-rubric',rows,result});document.getElementById('rubric-save').onclick=()=>{data.rubrics.unshift({date:Date.now(),rows});data.rubrics=data.rubrics.slice(0,50);if(save())A.toast('Grading record saved locally.');};};}
  function workspace(){setHTML(title('Your local workspace.','Import answer files, revisit reports, and export only what you choose.','REPORT COLLECTION')+`<div class="result-summary"><div class="result-actions"><label class="secondary file-button">${h('Import a Brain Studio answer file')}<input type="file" id="profile-import" accept=".json,application/json"></label><button id="workspace-export" class="secondary">${h('Export assessment answers')}</button><button id="workspace-clear" class="text-button danger">${h('Clear this local workspace')}</button></div><p>${h('Imported profiles must contain complete answers for a supported instrument. Scores are recalculated; imported score claims are not trusted.')}</p></div><section class="saved-professional-profiles">${data.profiles.map(p=>`<article class="history-row"><div><h3>${nameHTML(p.name)} · ${h(descriptor(p.instrumentId).title)}</h3><p>${esc(new Date(p.date).toLocaleString(T.language))}</p></div><div class="history-tools"><button class="secondary" data-open-profile="${esc(p.id)}">${h('View report ↗')}</button><button class="text-button danger" data-delete-profile="${esc(p.id)}">${h('Delete local report')}</button></div></article>`).join('')}</section><div class="method-note"><h3>${h('Data and scientific boundaries')}</h3><p>${h('Your records are stored locally and are not encrypted by this app. Keep exports private. No diagnosis, percentile, validated job-fit score, or scientific translation certification is generated.')}</p><p>${h('Reference reports informed feature design, but their personal data, proprietary questions, norms, and scoring formulas are not distributed.')}</p></div>`);document.querySelectorAll('[data-open-profile]').forEach(button=>button.onclick=()=>{activeProfile=button.dataset.openProfile;A.navigate('portfolio');});document.getElementById('workspace-clear').onclick=()=>{if(!confirm(tr('Clear all local workspace profiles, drafts, notes, plans, feedback, and grading records? Export a copy first.')))return;const previous=data;data={drafts:{},profiles:[],models:[],plans:[],notes:{},feedbacks:[],rubrics:[]};if(save()){activeProfile=null;observerDraft=[{role:'self',ratings:{},priorities:[]},{role:'manager',ratings:{},priorities:[]}];feedbackResult=null;workspace();A.toast('Local workspace cleared. Existing exported files are unchanged.');}else data=previous;};document.querySelectorAll('[data-delete-profile]').forEach(button=>button.onclick=()=>{if(!confirm(tr('Delete this local report and its coaching notes? Exported files are unchanged.')))return;const previous=data.profiles,notes=data.notes;data.profiles=data.profiles.filter(p=>p.id!==button.dataset.deleteProfile);data.notes={...notes};delete data.notes[button.dataset.deleteProfile];if(save())workspace();else{data.profiles=previous;data.notes=notes;}});document.getElementById('workspace-export').onclick=reportExport({type:'assessment-answers',profiles:data.profiles});document.getElementById('profile-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2000000)return A.toast('Choose an answer file smaller than two megabytes.');try{const imported=JSON.parse(await file.text());const records=Array.isArray(imported.profiles)?imported.profiles:imported.profile?[imported.profile]:[imported];if(!records.length||records.length>100||new Set(records.map(record=>record?.id)).size!==records.length)throw new Error();const profiles=records.map(cleanProfile);if(profiles.some(p=>!p)||new Set(profiles.map(p=>p.id)).size!==profiles.length)throw new Error();for(const p of profiles)data.profiles=data.profiles.filter(x=>x.id!==p.id);data.profiles=[...profiles,...data.profiles].slice(0,100);if(save()){workspace();A.toast('Answer files imported and scores recalculated.');}}catch{A.toast('The answer file is incomplete, invalid, or uses an unsupported instrument.');}};}
  document.addEventListener('click',e=>{const link=e.target.closest?.('[data-source-link]');if(link&&window.desktop.openSource){e.preventDefault();window.desktop.openSource(link.href).catch(()=>A.toast('The source page could not be opened.'));}});
  window.ProfessionalUI={render(route){const page={library,instrument:questionnaire,portfolio,roles,coaching,development,team,feedback,skills,workspace}[route];if(!page)return false;page();return true;},get activeInstrument(){return activeInstrument;}};
  document.addEventListener('keydown',e=>{if(A.route!=='instrument'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;const key=({'١':'1','٢':'2','٣':'3','٤':'4','٥':'5','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5'}[e.key]||e.key);if(/^[1-5]$/.test(key)){const d=descriptor(activeInstrument),option=d.responseOptions[Number(key)-1];if(option){e.preventDefault();document.querySelector(`[data-prof-value="${option.value}"]`)?.click();}}else if(e.key==='Enter'&&(document.activeElement.id==='content'||document.activeElement.classList.contains('pro-option'))){e.preventDefault();document.getElementById('prof-next')?.click();}});
})();
